package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

type DataReader struct {
	reader *bufio.Reader
	tokens []string
	pos    int
}

func NewDataReader(r io.Reader) *DataReader {
	return &DataReader{reader: bufio.NewReader(r)}
}

func CreateFromFile(name string) *DataReader {
	f, err := os.Open(name)
	if err != nil {
		panic(err)
	}
	return NewDataReader(f)
}

func (d *DataReader) Next() (string, bool) {
	for d.tokens == nil || d.pos >= len(d.tokens) {
		s, err := d.reader.ReadString('\n')
		if err != nil && len(s) == 0 {
			return "", false
		}
		d.tokens = strings.Fields(s)
		d.pos = 0
	}
	t := d.tokens[d.pos]
	d.pos++
	return t, true
}

func (d *DataReader) NextToken() string {
	t, ok := d.Next()
	if !ok {
		panic("no more tokens")
	}
	return t
}

func (d *DataReader) NextInt() int {
	v, err := strconv.Atoi(d.NextToken())
	if err != nil {
		panic(err)
	}
	return v
}

func (d *DataReader) NextLong() int64 {
	v, err := strconv.ParseInt(d.NextToken(), 10, 64)
	if err != nil {
		panic(err)
	}
	return v
}

func (d *DataReader) ReadIntArray(n int) []int {
	result := make([]int, n)
	for i := range result {
		result[i] = d.NextInt()
	}
	return result
}

func (d *DataReader) NextLine() string {
	s, err := d.reader.ReadString('\n')
	if err != nil && len(s) == 0 {
		return ""
	}
	return strings.TrimRight(s, "\r\n")
}

func toYesNo(b bool) string {
	if b {
		return "YES"
	}
	return "NO"
}

func (d *DataReader) Solve(out *bufio.Writer) {
	n := d.NextInt()
	k := d.NextInt()

	s := d.NextToken()

	used := make([]bool, n)

	var dfs func(u int) bool
	dfs = func(u int) bool {
		if u < 0 || u >= n || used[u] || s[u] == '#' {
			return false
		}
		if s[u] == 'T' {
			return true
		}
		used[u] = true

		return dfs(u-k) || dfs(u+k)
	}

	fmt.Fprintln(out, toYesNo(dfs(strings.IndexByte(s, 'G'))))
}

func main() {
	var r io.Reader
	var out *bufio.Writer

	if os.Getenv("ONLINE_JUDGE") == "" {
		f, err := os.Open("input.txt")
		if err != nil {
			panic(err)
		}
		defer f.Close()
		r = f

		o, err := os.Create("output.txt")
		if err != nil {
			panic(err)
		}
		defer o.Close()
		out = bufio.NewWriter(o)
	} else {
		r = os.Stdin
		out = bufio.NewWriter(os.Stdout)
	}

	NewDataReader(r).Solve(out)
	out.Flush()
}

